@@ -30,3 +40,30 @@ export function t(key, lang = "en", params = {}) {

 /** Message keys per language, for checks. */
 export const messageKeys = (lang) => Object.keys(MESSAGES[lang] ?? {});
+
+/**
+ * The supported language an `Accept-Language` header prefers most (by q-value,
+ * then order; region tags like `ko-KR` count as `ko`), else `fallback`.
+ */
+export function pickLanguage(header, fallback = LANGUAGES[0]) {
+  if (Array.isArray(header)) header = header.join(",");
+  if (typeof header !== "string") return fallback;
+  let best = null;
+  let bestQ = 0;
+  for (const part of header.split(",")) {
+    const [tag, ...params] = part.trim().split(";");
+    const lang = tag.trim().toLowerCase().split("-")[0];
+    if (!LANGUAGES.includes(lang)) continue;
+    let q = 1;
+    for (const p of params) {
+      const [k, v] = p.split("=").map((x) => x.trim());
+      if (k.toLowerCase() !== "q") continue;
+      q = /^(0(\.\d{0,3})?|1(\.0{0,3})?)$/.test(v ?? "") ? Number(v) : 0;
+    }
+    if (q > bestQ) {
+      best = lang;
+      bestQ = q;
+    }
+  }
+  return best ?? fallback;
+}
